"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["83395"],{93611(e,i,t){t.r(i),t.d(i,{metadata:()=>a,default:()=>u,frontMatter:()=>c,contentTitle:()=>p,toc:()=>l,assets:()=>d});var a=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-participant-delink-abha-policy","title":"De-link ABHA policies","description":"Removes specific products from a member\'s policy link for a payer, keyed on payerid, memberid and the products listed.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-participant-delink-abha-policy.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-participant-delink-abha-policy","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-participant-delink-abha-policy","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"De-link ABHA policies","sidebar_label":"De-link ABHA policies","sidebar_class_name":"api-method api-method--post","description":"Removes specific products from a member\'s policy link for a payer, keyed on payerid, memberid and the products listed.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Validate ABHA policy link (v2)","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate"},"next":{"title":"De-link ABHA policies (V2)","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-delink-abha-policy"}}'),n=t(62540),r=t(43023),s=t(44136),o=JSON.parse('{"id":"registry_participant_delink_abha_policy","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/participant/delink/abha/policy","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"De-link ABHA policies","description":"Removes specific products from a member\'s policy link for a payer, keyed on payerid, memberid and the products listed.\\n\\n### Business purpose\\n\\nPolicies lapse, members leave a product, and insurance companies move between TPAs. This call is the only documented way to reverse a link written through /participant/link/abha/policy, which keeps the registry honest so that providers do not route claims against coverage that no longer exists. Because there is no in-place re-parenting operation, de-link followed by a fresh link is also the documented procedure when a payer changes its processing TPA. The insurer and TPA control their own data; providers get accurate policy lookups.\\n\\n### When to use\\n\\nUse it when a product should no longer be discoverable for a member: policy termination, member removal, product migration, or the first half of a TPA change. It belongs to the member layer and precedes no claim-side workflow; it is the payer\'s use case 3 in the sandbox exit checklist (Link, Get Policy, De-Link). Do not use it to correct an ABHA number, which is what /update/abhanumber is for.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_id, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer <token> (the participant service uses bearer_auth, not Authorization).\\n- Base path for the participant service: https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation id are involved.\\n- The caller must be the participant named as payerid or processingid when the policies were linked; NHCX extracts the client id from the token and allows the call only on a match.\\n- The body is ParticipantDeLinkAbhaRequest: requestid (UUID), payerid, memberid and policies (productid, productname) are required; processingid is optional. There is no abhanumber field.\\n\\n### Postconditions\\n\\nA successful call returns HTTP 200 with ParticipantDeLinkAbhaResponse and the listed products are no longer returned by /participant/get/policies for that payer and member. No asynchronous callback follows. If the caller is not the linking payer or TPA the call is refused with an error message; if a listed product is not linked the response carries \\"There is no policies with requested details\\". Other failures return 400, 404 or 500 with the ErrorResponse envelope. To re-establish coverage, call the link endpoint again, optionally with a new processingid.\\n\\n### Common mistakes\\n\\n- Calling from a participant that is neither the payerid nor the processingid used at link time; NHCX checks the client id in the token, not the body, and refuses the call (common mistake 10).\\n- Listing a product that is not actually linked for that payerid and memberid, which returns the error message \\"There is no policies with requested details\\".\\n- Including abhanumber or mobilenumber in the body; the de-link request is keyed on payerid, memberid and the products listed, and has no ABHA field.\\n- Expecting provider-side caches to update: the handbook documents the policy cache as permanent with no TTL, so a de-linked policy keeps appearing until the provider passes forceRefresh: true.\\n- Using a token generated with a different client_id from the one used when the payer or TPA participant was created.\\n\\n### Best practices\\n\\n- De-link only the specific products that need removing; the policies array is the unit of work.\\n- When moving an insurer to a new TPA, follow the documented order: de-link the existing policies, then link them again with the new TPA\'s participant code as processingid.\\n- Generate a fresh UUID for requestid on every call and log it with the response.\\n- Confirm the result with /participant/get/policies afterwards, and remember that providers may need a forced refresh of their own policy cache.\\n- Refresh the Bearer token proactively and retry once on 401 before escalating.\\n\\n### Related scenario\\n\\nAn insurance company ends its contract with one TPA and appoints another. Its integration first calls /participant/get/policies to enumerate the products linked for each affected member, then calls /participant/delink/abha/policy for each member with the insurer\'s participant code as payerid, the member id and the products to remove. Once every de-link returns success, it calls /participant/link/abha/policy again with the new TPA\'s participant code as processingid. Hospitals that have cached these members\' policies are told to refresh, so that their next coverage-eligibility check is addressed to the new TPA.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"requestid","type":"string","required":false,"description":"","encrypted":false},{"name":"payerid","type":"string","required":false,"description":"","encrypted":false},{"name":"memberid","type":"string","required":false,"description":"","encrypted":false},{"name":"policies","type":"object[]","required":false,"description":"","encrypted":false},{"name":"policies.productid","type":"string","required":false,"description":"","encrypted":false},{"name":"policies.productname","type":"string","required":false,"description":"","encrypted":false},{"name":"processingid","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"requestid":"9a7c5e3d-1b2f-4c8a-b6d4-0e9f8a7b6c55","payerid":"100234@sbx","memberid":"MEM-2026-000123","policies":[{"productid":"PRD-FLOATER-01","productname":"Family Floater Gold"}],"processingid":"100235@sbx"},"responses":[{"status":"200","description":"A successful call returns HTTP 200 with ParticipantDeLinkAbhaResponse and the listed products are no longer returned by /participant/get/policies for that payer and member.","example":{"result":"success"}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/delink/abha/policy \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"requestid\\": \\"9a7c5e3d-1b2f-4c8a-b6d4-0e9f8a7b6c55\\",\\n  \\"payerid\\": \\"100234@sbx\\",\\n  \\"memberid\\": \\"MEM-2026-000123\\",\\n  \\"policies\\": [\\n    {\\n      \\"productid\\": \\"PRD-FLOATER-01\\",\\n      \\"productname\\": \\"Family Floater Gold\\"\\n    }\\n  ],\\n  \\"processingid\\": \\"100235@sbx\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/delink/abha/policy \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"requestid\\": \\"9a7c5e3d-1b2f-4c8a-b6d4-0e9f8a7b6c55\\",\\n  \\"payerid\\": \\"100234@sbx\\",\\n  \\"memberid\\": \\"MEM-2026-000123\\",\\n  \\"policies\\": [\\n    {\\n      \\"productid\\": \\"PRD-FLOATER-01\\",\\n      \\"productname\\": \\"Family Floater Gold\\"\\n    }\\n  ],\\n  \\"processingid\\": \\"100235@sbx\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/delink/abha/policy\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"requestid\\": \\"9a7c5e3d-1b2f-4c8a-b6d4-0e9f8a7b6c55\\",\\n        \\"payerid\\": \\"100234@sbx\\",\\n        \\"memberid\\": \\"MEM-2026-000123\\",\\n        \\"policies\\": [\\n            {\\n                \\"productid\\": \\"PRD-FLOATER-01\\",\\n                \\"productname\\": \\"Family Floater Gold\\"\\n            }\\n        ],\\n        \\"processingid\\": \\"100235@sbx\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/delink/abha/policy\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"requestid\\": \\"9a7c5e3d-1b2f-4c8a-b6d4-0e9f8a7b6c55\\",\\n    \\"payerid\\": \\"100234@sbx\\",\\n    \\"memberid\\": \\"MEM-2026-000123\\",\\n    \\"policies\\": [\\n      {\\n        \\"productid\\": \\"PRD-FLOATER-01\\",\\n        \\"productname\\": \\"Family Floater Gold\\"\\n      }\\n    ],\\n    \\"processingid\\": \\"100235@sbx\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"De-link ABHA policies",sidebar_label:"De-link ABHA policies",sidebar_class_name:"api-method api-method--post",description:"Removes specific products from a member's policy link for a payer, keyed on payerid, memberid and the products listed.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},p,d={},l=[];function h(e){return(0,n.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:i}={...(0,r.R)(),...e.components};return i?(0,n.jsx)(i,{...e,children:(0,n.jsx)(h,{...e})}):h(e)}}}]);